--
-- Name: admin_audit_log; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_audit_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    action character varying(50) NOT NULL,
    result character varying(20) NOT NULL,
    resource_type character varying(30),
    resource_id uuid,
    admin_note character varying(500),
    request_ip character varying(45),
    user_agent character varying(500),
    request_path character varying(200),
    error_message character varying(500),
    created_at timestamp without time zone DEFAULT now() NOT NULL
);


--
-- Name: agent_session; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_session (
    thread_id uuid DEFAULT gen_random_uuid() NOT NULL,
    work_id uuid NOT NULL,
    writer_id uuid NOT NULL,
    scenario character varying(40) NOT NULL,
    title text,
    messages jsonb DEFAULT '[]'::jsonb NOT NULL,
    summary_so_far text,
    status character varying(20) DEFAULT 'active'::character varying NOT NULL,
    last_activity_at timestamp without time zone DEFAULT now() NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_session_scenario_check CHECK (((scenario)::text = ANY ((ARRAY['auto'::character varying, 'card_auto'::character varying, 'draft_next'::character varying, 'consistency_check'::character varying, 'revision'::character varying, 'extraction'::character varying, 'qa'::character varying, 'ideation'::character varying])::text[]))),
    CONSTRAINT agent_session_status_check CHECK (((status)::text = ANY ((ARRAY['active'::character varying, 'closed'::character varying])::text[])))
);


