CREATE TABLE public.ai_job (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    writer_id uuid NOT NULL,
    work_id uuid NOT NULL,
    episode_id uuid,
    job_type character varying(30) NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    error_message text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT ai_job_job_type_check CHECK (((job_type)::text = ANY ((ARRAY['indexing'::character varying, 'summary'::character varying, 'review'::character varying, 'generation'::character varying])::text[]))),
    CONSTRAINT ai_job_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying, 'done'::character varying, 'failed'::character varying])::text[])))
);


