-- Name: COLUMN episode_summary.pov_character; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.pov_character IS '회차 시점 인물 — 시점 일관성 검수 / 시점별 필터.';


--
-- Name: COLUMN episode_summary.present_characters; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.present_characters IS '회차 등장 인물명 배열. JSONB containment(@>) 로 인물 검색.';


--
-- Name: COLUMN episode_summary.present_locations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.present_locations IS '회차 등장 장소 배열.';


--
-- Name: COLUMN episode_summary.key_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.key_events IS '시간순 핵심 사건 [{order,event}]. 다음 화 초안 컨텍스트.';


--
-- Name: COLUMN episode_summary.time_progression; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.time_progression IS '회차 내 시간 흐름 (예: "한 시간","하루","3년").';


--
-- Name: COLUMN episode_summary.tone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.tone IS '회차 톤 (예: "잔잔한 일상","긴장감 고조"). 톤 일관성 검수.';


--
-- Name: COLUMN episode_summary.cliffhanger; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.cliffhanger IS '회차 끝점 / 다음 화 hook. 초안 입력에 활용.';


--
-- Name: COLUMN episode_summary.referenced_world_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.referenced_world_notes IS '회차에서 참조된 world_note id 배열.';


--
-- Name: COLUMN episode_summary.foreshadow_planted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.foreshadow_planted IS '회차에서 새로 심은 복선 candidates [{name,description}].';


--
-- Name: COLUMN episode_summary.foreshadow_paid_off; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.foreshadow_paid_off IS '회차에서 회수된 기존 foreshadow id 배열.';


--
-- Name: COLUMN episode_summary.keywords; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.keywords IS '검색 보조 키워드 5~10개. tsvector 보완.';


--
-- Name: COLUMN episode_summary.content_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.content_hash IS 'episode.content SHA256. 동일 본문 재 호출 skip.';


--
-- Name: COLUMN episode_summary.generation_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.generation_count IS '누적 재생성 횟수 — 일 limit 적용.';


--
-- Name: COLUMN episode_summary.last_generated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.episode_summary.last_generated_at IS '마지막 호출 시각 — 30분 cooldown 적용.';


--
-- Name: export; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.export (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    writer_id uuid NOT NULL,
    work_id uuid NOT NULL,
    format character varying(20) NOT NULL,
    status character varying(20) NOT NULL,
    file_url character varying(500),
    expires_at timestamp without time zone,
    created_at timestamp without time zone DEFAULT now() NOT NULL
);


--
-- Name: extraction_suggestion; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.extraction_suggestion (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    writer_id uuid NOT NULL,
    work_id uuid NOT NULL,
    episode_id uuid,
    entity_type character varying(30) NOT NULL,
    suggested_name text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    confirmed_target_id uuid,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    source_agent character varying(40),
    source_thread_id uuid,
    reviewer_note text,
    CONSTRAINT extraction_suggestion_entity_type_check CHECK (((entity_type)::text = ANY ((ARRAY['character'::character varying, 'world_note'::character varying, 'term'::character varying, 'character_update'::character varying, 'character_delete'::character varying, 'world_note_update'::character varying, 'world_note_delete'::character varying, 'plot_create'::character varying, 'plot_tree'::character varying, 'plot_revision'::character varying, 'plot_delete'::character varying, 'episode_draft'::character varying, 'episode_update'::character varying, 'episode_delete'::character varying, 'review_issue'::character varying])::text[]))),
    CONSTRAINT extraction_suggestion_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'confirmed'::character varying, 'rejected'::character varying])::text[])))
);


--
-- Name: foreshadow; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.foreshadow (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
