    plot_id uuid,
    context_memo text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT foreshadow_link_check CHECK (((episode_id IS NOT NULL) OR (plot_id IS NOT NULL)))
);


