);


--
-- Name: token_receipt; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.token_receipt (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    writer_id uuid NOT NULL,
    work_id uuid,
    feature character varying(40) NOT NULL,
    scenario character varying(40) NOT NULL,
    reference_type character varying(40) NOT NULL,
    reference_id uuid NOT NULL,
    total_user_tokens integer DEFAULT 0 NOT NULL,
    total_input_raw integer DEFAULT 0 NOT NULL,
    total_output_raw integer DEFAULT 0 NOT NULL,
    cache_read_tokens integer DEFAULT 0 NOT NULL,
    cache_create_tokens integer DEFAULT 0 NOT NULL,
    status character varying(20) NOT NULL,
    abort_reason character varying(40),
    duration_ms integer,
    idempotency_key character varying(200),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT token_receipt_status_check CHECK (((status)::text = ANY ((ARRAY['success'::character varying, 'partial'::character varying, 'failed'::character varying])::text[])))
);


--
-- Name: token_receipt_line; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.token_receipt_line (
    id bigint NOT NULL,
    receipt_id uuid NOT NULL,
    seq integer NOT NULL,
    step_type character varying(40) NOT NULL,
    actor character varying(40) NOT NULL,
    tool_name character varying(60),
    input_tokens integer DEFAULT 0 NOT NULL,
    output_tokens integer DEFAULT 0 NOT NULL,
    user_tokens integer DEFAULT 0 NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT token_receipt_line_step_type_check CHECK (((step_type)::text = ANY ((ARRAY['planner_call'::character varying, 'tool_call'::character varying, 'worker_call'::character varying, 'compression'::character varying])::text[])))
);


--
-- Name: token_receipt_line_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.token_receipt_line_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: token_receipt_line_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.token_receipt_line_id_seq OWNED BY public.token_receipt_line.id;


